import {createEnhancements} from './enhancements.mjs';
import {FILES,parseCSV,prepare,outputFiles} from './solver.mjs';import{makeZIP}from './zip.mjs';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let data=null,results={},scenario='A',view='timeline',busy=false,worker=null,baselineResults={},experimentalResults={},mode='baseline',experiment=null;const titles={A:'Strict supply',B:'Strict schedule',C:'Balanced'},descriptions={A:'Supply stays fixed. Completion dates absorb congestion.',B:'Meet every planned date. Pay only for the additional access and extended nights needed.',C:'Balance priority-weighted delays against extra access and extended working nights.'};const fmt=x=>Number(x).toLocaleString(undefined,{maximumFractionDigits:1});
function message(s,error=false){$('message').textContent=s;$('message').classList.toggle('error',error);}function setBusy(v){busy=v;for(const id of ['run','example','files'])$(id).disabled=v||id==='run'&&!data;$('export').disabled=v||!results[scenario]?.report.feasible;$('export-all').disabled=v||!['A','B','C'].every(s=>results[s]?.report.feasible);}
function loaded(d,name){prepare(d);data=d;results={};baselineResults={};experimentalResults={};mode='baseline';experiment=null;$('inspector').hidden=true;$('instance-status').textContent=name+' · '+d['07_PROJECT_DETAILS'].length+' contract/type records · '+d['08_ACTIVITY_DETAILS'].length+' activities · '+d['04_LOCATION_SUPPLY'].length+' locations';message('Instance checked. Generate schedules to compare all three scenarios.');render();setBusy(false);}
$('example').onclick=async()=>{try{loaded(await(await fetch('example.json')).json(),'Supplied planning instance');}catch(e){message(e.message,true);}};
$('files').onchange=async e=>{try{const d={};for(const f of e.target.files){const name=f.name.replace(/\(\d+\)(?=\.csv$)/,'').replace(/\.csv$/i,'');if(!FILES.includes(name))continue;if(d[name])throw Error('Duplicate input: '+name);if(f.size>20*1024*1024)throw Error(f.name+' exceeds 20 MB');d[name]=parseCSV(await f.text());}loaded(d,'Uploaded planning instance');}catch(e){message(e.message,true);e.target.value='';}};
function generate(isExperiment=false){if(!data||busy)return;if(!isExperiment){baselineResults={};experimentalResults={};experiment=null;mode='baseline';results=baselineResults;}else{experimentalResults={};results=experimentalResults;mode='experiment';}$('inspector').hidden=true;setBusy(true);render();worker=new Worker('worker.mjs',{type:'module'});worker.onmessage=e=>{const x=e.data;if(x.type==='progress')message((isExperiment?'Re-planning experiment':'Scheduling baseline')+' '+x.scenario+' — comparing constraints and placements…');if(x.type==='result'){results[x.scenario]=x.result;render();}if(x.type==='done'){worker.terminate();worker=null;setBusy(false);render();const all=Object.values(results).every(r=>r.report.feasible);message(all?(isExperiment?'What-if complete. Compare the changes below; your submission baseline is preserved.':'Baseline schedules pass the implemented checks. You can now run a what-if comparison.'):'Some candidates fail checks. Review diagnostics; failing schedules cannot be exported.',!all);}if(x.type==='error'){worker.terminate();worker=null;setBusy(false);render();message(x.message,true);}};worker.onerror=e=>{worker?.terminate();worker=null;setBusy(false);render();message('Scheduling failed: '+e.message,true);};worker.postMessage({data,options:isExperiment?experiment:{},baselines:isExperiment?baselineResults:{}});}
$('run').onclick=()=>generate(false);
document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>{scenario=b.dataset.scenario;$('inspector').hidden=true;render();});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});$('line').onchange=render;$('search').oninput=render;
function download(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}function exportZip(all){const files={};for(const s of all?['A','B','C']:[scenario]){const r=results[s];if(!r?.report.feasible)return;for(const [name,content]of Object.entries(outputFiles(r)))files[(all?s+'/':'')+name]=content;}if(mode==='experiment')files['EXPERIMENT_README.json']=JSON.stringify({label:'WHAT-IF ONLY — not the original submission baseline',changes:experiment},null,2);download(mode==='experiment'?(all?'WhatIf_ABC.zip':'WhatIf_'+scenario+'.zip'):(all?'PS1_Results_ABC.zip':'Scenario_'+scenario+'.zip'),makeZIP(files));}$('export').onclick=()=>exportZip(false);$('export-all').onclick=()=>exportZip(true);
function filtered(r){const q=$('search').value.toLowerCase(),line=$('line').value;return r.modelInfo.activities.filter(a=>(!line||a.line===line)&&(!q||(a.id+' '+a.contract).toLowerCase().includes(q)));}
function table(headers,rows){return '<div class="scroll"><table><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function render(){enhancements.render();$('export-all').textContent=mode==='experiment'?'Download experiment ↓':'Download all scenarios ↓';document.querySelectorAll('[data-scenario]').forEach(b=>{b.classList.toggle('selected',b.dataset.scenario===scenario);b.setAttribute('aria-pressed',b.dataset.scenario===scenario);});document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));for(const s of ['A','B','C']){const r=results[s];$('score-'+s).textContent=r?fmt(r.report.objective_score):'—';$('meta-'+s).textContent=r?(r.report.feasible?'Checks passed':'Checks failed')+' · '+r.report.complete+'/'+r.report.total+' activities delivered':'Generate schedules to compare';}$('scenario-title').textContent='Scenario '+scenario+' · '+titles[scenario];$('scenario-description').textContent=descriptions[scenario];const r=results[scenario];$('export').disabled=busy||!r?.report.feasible;$('export-all').disabled=busy||!['A','B','C'].every(s=>results[s]?.report.feasible);$('validation-badge').textContent=r?(r.report.feasible?'Implemented checks passed':'Review violations'):'Awaiting schedule';$('validation-badge').className='badge '+(r?(r.report.feasible?'good':'bad'):'');if(!r){$('metrics').innerHTML=['Workload delivered','Contract-overrun days','Extra access slots','Extended nights'].map(x=>'<article><span>'+x+'</span><strong>—</strong></article>').join('');$('view').innerHTML='<div class="empty"><span>01 / LOAD THE DEMAND BOOK</span><h3>Your planning timeline starts here.</h3><p>Load the dataset, then generate A, B and C.</p></div>';return;}
const p=r.report;$('metrics').innerHTML=[['Workload delivered',p.complete+' / '+p.total,'activities'],['Contract-overrun days',fmt(p.overrun_days_total),p.contracts_overrunning+' contracts late'],['Extra access slots',fmt(p.excess_access_nights_total),'summed by location-week'],['Extended nights',p.eclo_nights_total,'ECLO access records']].map(([l,n,s])=>'<article><span>'+l+'</span><strong>'+n+' <small>'+s+'</small></strong></article>').join('');
const names={timeline:['Activity access plan','Each coloured cell is an access. Select an activity to inspect its route, dates and constraints.'],contracts:['Contract delivery','Completion is the Sunday of the final access week. Overrun is measured against the planned date.'],capacity:['Capacity & validation','These are local checks against our reading of the brief; official validation is still required.'],network:['Dual-line network','Platforms and tunnel sectors are independent per line and bound. Live work couples both bounds and the interchange.']};$('view-title').textContent=names[view][0];$('view-help').textContent=names[view][1];
if(view==='timeline'){const aa=filtered(r),weeks=Math.max(r.modelInfo.horizon,r.last);$('view').innerHTML='<div class="scroll"><table class="timeline"><thead><tr><th>Activity / contract</th>'+Array.from({length:weeks},(_,i)=>'<th title="Week '+(i+1)+'">'+(i+1)+'</th>').join('')+'</tr></thead><tbody>'+aa.map(a=>{const accesses=new Map(r.access.filter(x=>x.activity_id===a.id).map(x=>[x.week,x]));return '<tr><td><button data-inspect="'+esc(a.id)+'">'+esc(a.id)+' · '+esc(a.contract)+'</button><small>'+esc(a.line)+' '+esc(a.bound)+' · P'+a.priority+'</small></td>'+Array.from({length:weeks},(_,i)=>{const x=accesses.get(i+1);return '<td>'+(x?'<button data-inspect="'+esc(a.id)+'" aria-label="Inspect '+esc(a.id)+' week '+(i+1)+'"><span class="cell '+a.line.toLowerCase()+(x.eclo?' eclo':'')+(i+1>a.due?' late':'')+'" title="Week '+(i+1)+' · '+(x.eclo?'ECLO: 1.5':'Standard: 1')+' units"></span></button>':'')+'</td>';}).join('')+'</tr>';}).join('')+'</tbody></table></div><div class="legend"><span><i></i>Alpha</span><span><i class="blue"></i>Beta</span><span><i class="amber"></i>ECLO</span><span><i class="red"></i>After planned completion</span><span>Week 1 starts '+esc(r.modelInfo.start)+'</span></div>';}
if(view==='contracts'){$('view').innerHTML=table(['Contract','Priority','Planned completion','Scheduled completion','Overrun','Activities'],r.results.filter(x=>filtered(r).some(a=>a.contract===x.contract_number)).map(x=>{const pp=data['07_PROJECT_DETAILS'].find(p=>p.contract_number===x.contract_number);return[esc(x.contract_number),'P'+esc(pp.contract_priority),esc(pp.planned_completion_date),esc(x.simulated_completion_date),x.overrun_days?'<b style="color:#a84f24">'+x.overrun_days+' days</b>':'On time',r.modelInfo.activities.filter(a=>a.contract===x.contract_number).length];}));}
if(view==='capacity'){const rules=['workload','planned_start','predecessor','closure','mix','allocation','workfront','capacity','eclo','eclo_window','frequency','occupancy','results'];$('view').innerHTML='<div class="info" style="margin:0 22px 18px">Penalty: '+fmt(p.priority_weighted_score)+' weighted delay'+(scenario==='B'?' (excluded in B)':'')+' + '+p.excess_access_nights_total+' × 7 extra slots + '+p.eclo_nights_total+' × 5 extended nights. Scenario A excludes the latter two terms.</div><div class="checks">'+rules.map(rule=>{const v=p.hard_violations.filter(x=>x.rule===rule);return '<div class="check '+(v.length?'bad':'')+'">'+(v.length?'✕':'✓')+' '+esc(rule.replaceAll('_',' '))+(v.length?' — '+v.map(x=>esc(x.detail)).join('; '):' · passed')+'</div>';}).join('')+'</div>'+table(['Week','Location','Possessions','Nominal capacity','Extra slots'],p.hotspots.filter(x=>!$('line').value||x.location.includes(':'+ $('line').value+':')).map(x=>[x.week,'<button class="table-button" data-hotspot="'+p.hotspots.indexOf(x)+'">'+esc(x.location)+'</button>',x.used,x.capacity,x.excess]));}
if(view==='network'){const stations=data['02_STATIONS'],lines=data['01_LINES'];$('view').innerHTML='<div class="network"><svg viewBox="0 0 1050 '+(lines.length*110+30)+'" role="img" aria-label="Network station sequence by line">'+lines.map((l,i)=>{const ss=stations.filter(s=>s.line_code===l.line_code).sort((a,b)=>+a.seq-+b.seq),y=60+i*110,color=i?'#447bc3':'#168f78';return '<text x="15" y="'+(y-22)+'" class="line-label">'+esc(l.line_name)+'</text><line x1="95" x2="985" y1="'+y+'" y2="'+y+'" stroke="'+color+'" stroke-width="5"/>'+ss.map((s,j)=>{const x=95+j*890/Math.max(1,ss.length-1);return '<circle cx="'+x+'" cy="'+y+'" r="'+(s.is_interchange==='1'?10:7)+'" fill="white" stroke="'+color+'" stroke-width="3"/><text x="'+x+'" y="'+(y+30)+'" text-anchor="middle">'+esc(s.station_id)+'</text>';}).join('');}).join('')+'</svg></div><div class="network-info"><div class="info">H01–H02: independent Alpha/Beta tracks. Only Live power closures cross between lines at the interchange. Live closures also mirror onto the opposite bound.</div><p class="muted">This diagram shows topology, not a live operational possession display. Inspect an activity to see its occupied locations and full safety footprint.</p></div>';}
$('view').querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>inspect(b.dataset.inspect));}
function inspect(id){const r=results[scenario],a=r.modelInfo.activities.find(x=>x.id===id),xx=r.access.filter(x=>x.activity_id===id),first=Math.min(...xx.map(x=>x.week)),last=Math.max(...xx.map(x=>x.week)),delays=r.decisions[id]||[],eclo=xx.filter(x=>x.eclo).length,units=xx.reduce((s,x)=>s+1+.5*x.eclo,0),earliest=a.start+Math.ceil(a.workload)-1;$('inspector').hidden=false;$('inspector').innerHTML='<div class="inspector-top"><div><p class="eyebrow">ACTIVITY DETAIL · SCENARIO '+scenario+'</p><h2>'+esc(a.id)+' / '+esc(a.contract)+' · '+esc(a.line)+' '+esc(a.bound)+'</h2><p class="muted">'+esc(a.nature)+' · '+esc(a.access_type)+' possession · Contract priority '+a.priority+'</p></div><button id="close-inspector" aria-label="Close activity detail">Close ×</button></div><div class="detail-grid">'+[['Delivered / required',units+' / '+a.workload+' units'],['Scheduled weeks',first+'–'+last],['Earliest start / target','W'+a.start+' / W'+a.due],['Extended nights',eclo]].map(([l,n])=>'<article><span>'+l+'</span><strong>'+n+'</strong></article>').join('')+'</div><div class="info">'+(a.predecessor?'Must follow '+esc(a.predecessor)+' in a strictly later week. ':'No predecessor. ')+(earliest>a.due?'Even without congestion, standard nights finish no earlier than week '+earliest+', after the target. ':'The start date and workload can fit before the target in isolation. ')+(last>a.due?'This plan finishes '+((last-a.due)*7)+' calendar days after the target week.':'This plan finishes within the target week.')+'</div>'+(delays.length?'<div class="info warning">Deferred in weeks '+delays.map(x=>x.week).join(', ')+': buffers, possession capacity or contractor access/team limits prevented a placement in the attempted plan.</div>':'')+'<h3>Occupied route</h3><p class="path">'+a.core.map(esc).join(' → ')+'</p><details><summary>Safety footprint: '+a.footprint.length+' locations</summary><p class="path">'+a.footprint.map(esc).join('<br>')+'</p></details><h3>Access records</h3>'+table(['Sequence','Week','Contract night index','Yield','Possession group'],xx.map(x=>[x.access_seq,x.week,x.access_night,x.eclo?'1.5 · ECLO':'1.0',esc(r.occupancy.find(o=>o.activity_id===id&&o.week===x.week)?.co_share_group)]));$('close-inspector').onclick=()=>{$('inspector').hidden=true;};enhancements.inspect(id);$('inspector').scrollIntoView({behavior:'smooth',block:'start'});}
// Feature-detected declarative tools expose the same visible UI actions.
if(navigator.modelContext?.registerTool){try{navigator.modelContext.registerTool({name:'generate_track_schedules',description:'Generate A, B and C schedules for the currently loaded planning instance.',inputSchema:{type:'object',properties:{}},execute:async()=>{if(!data)return {content:[{type:'text',text:'Load a planning instance first.'}]};$('run').click();return{content:[{type:'text',text:'Scheduling started. Results appear in the visible workspace.'}]};}});}catch{}}
const enhancements=createEnhancements({state:()=>({data,results,baseline:baselineResults,experimental:experimentalResults,mode,experiment,scenario,busy}),download,inspect,selectScenario:s=>{scenario=s;$('inspector').hidden=true;render();},experiment:exp=>{if(busy)return;prepare(data,exp);experiment=structuredClone(exp);$('experiment-error').textContent='';generate(true);},reset:()=>{if(busy)return;mode='baseline';results=baselineResults;experimentalResults={};experiment=null;$('inspector').hidden=true;render();},showMode:m=>{if(busy)return;mode=m;results=m==='baseline'?baselineResults:experimentalResults;$('inspector').hidden=true;render();}});
render();
